#!/usr/bin/env bash
# EC2 schedules generated by finops-arbitrage-engine.
# Review before running. Prints the commands by default; DRY_RUN=0 executes them.
# Needs: aws CLI v2, and ROLE_ARN = an IAM role EventBridge Scheduler can assume
# with ec2:StartInstances / ec2:StopInstances on these instances.
set -euo pipefail
DRY_RUN="${DRY_RUN:-1}"
ROLE_ARN="${ROLE_ARN:?set ROLE_ARN to the scheduler execution role ARN}"
TZ_NAME="UTC"   # windows below were measured in UTC

run() { if [ "$DRY_RUN" = "1" ]; then printf "%q " "$@"; echo; else "$@"; fi; }

schedule() {  # name cron-expression action instance_id
  local name="$1" expr="$2" action="$3" iid="$4" target
  target=$(printf '{"Arn":"arn:aws:scheduler:::aws-sdk:ec2:%s","RoleArn":"%s","Input":"{\\"InstanceIds\\":[\\"%s\\"]}"}' "$action" "$ROLE_ARN" "$iid")
  run aws scheduler create-schedule --name "$name" \
    --schedule-expression "$expr" --schedule-expression-timezone "$TZ_NAME" \
    --flexible-time-window Mode=OFF --target "$target"
}

# i-0a1b2c3d4e5f60012 training-sandbox (p4d.24xlarge) — saves ~$16,020/mo [measured]
# idle 99% of observed time. Snapshot, then stop:
# run aws ec2 create-image --instance-id i-0a1b2c3d4e5f60012 --name finops-backup-i-0a1b2c3d4e5f60012 --no-reboot
# run aws ec2 stop-instances --instance-ids i-0a1b2c3d4e5f60012

# i-0a1b2c3d4e5f60011 llm-inference-prod (g5.12xlarge) — saves ~$2,660/mo [measured]
# window: stop 20:00→08:00 UTC on weeknights; off Sat–Sun
schedule "finops-stop-i-0a1b2c3d4e5f60011-20" "cron(0 20 ? * MON,TUE,WED,THU,FRI *)" stopInstances i-0a1b2c3d4e5f60011
schedule "finops-start-i-0a1b2c3d4e5f60011-08" "cron(0 8 ? * MON,TUE,WED,THU,FRI *)" startInstances i-0a1b2c3d4e5f60011

# i-0a1b2c3d4e5f60014 rag-api (g6.12xlarge) — saves ~$2,392/mo [estimated]
# right-size i-0a1b2c3d4e5f60014: g6.12xlarge → g6.4xlarge (~$2,392/mo). Needs a stop; do it in a window:
# run aws ec2 stop-instances --instance-ids i-0a1b2c3d4e5f60014
# run aws ec2 wait instance-stopped --instance-ids i-0a1b2c3d4e5f60014
# run aws ec2 modify-instance-attribute --instance-id i-0a1b2c3d4e5f60014 --instance-type Value=g6.4xlarge
# run aws ec2 start-instances --instance-ids i-0a1b2c3d4e5f60014

# i-0a1b2c3d4e5f60013 embedding-batch (g5.4xlarge) — saves ~$1,086/mo [measured]
# window: stop 04:00→02:00 UTC every night
schedule "finops-stop-i-0a1b2c3d4e5f60013-04" "cron(0 4 ? * MON,TUE,WED,THU,FRI,SAT,SUN *)" stopInstances i-0a1b2c3d4e5f60013
schedule "finops-start-i-0a1b2c3d4e5f60013-02" "cron(0 2 ? * MON,TUE,WED,THU,FRI,SAT,SUN *)" startInstances i-0a1b2c3d4e5f60013

# i-0a1b2c3d4e5f60015 ci-runner (c5.4xlarge) — saves ~$186/mo [measured]
# window: stop 23:00→08:00 UTC every night
schedule "finops-stop-i-0a1b2c3d4e5f60015-23" "cron(0 23 ? * MON,TUE,WED,THU,FRI,SAT,SUN *)" stopInstances i-0a1b2c3d4e5f60015
schedule "finops-start-i-0a1b2c3d4e5f60015-08" "cron(0 8 ? * MON,TUE,WED,THU,FRI,SAT,SUN *)" startInstances i-0a1b2c3d4e5f60015

